<script lang="ts" setup>
import { isString } from '@/utils/is'
import { sanitizeSvgContent } from '@/utils/sanitizeHtml'
import { computed, ref, watchEffect } from 'vue'

const props = defineProps<Props>()

// 存储从远程获取的 SVG 内容
const remoteSvgContent = ref<string>('')
const isLoadingSvg = ref(false)

// 检查是否为 SVG 源代码
const isSvgCode = (content: string): boolean => {
  if (!content) return false
  const trimmed = content.trim()
  return trimmed.startsWith('<svg') && trimmed.includes('</svg>')
}

// 检测 URL 是否为 SVG
const isSvgUrl = (url: string): boolean => {
  if (!url) return false
  // 检查 URL 是否以 .svg 结尾（忽略查询参数）
  const urlWithoutQuery = url.split('?')[0].toLowerCase()
  return urlWithoutQuery.endsWith('.svg')
}

// 清理和处理 SVG 内容
const sanitizeSvg = (svgText: string): string => {
  return sanitizeSvgContent(svgText)
}

// 获取远程 SVG 内容或处理 SVG 源代码
const fetchSvgContent = async (content: string) => {
  // 如果是 SVG 源代码，直接处理
  if (isSvgCode(content)) {
    remoteSvgContent.value = sanitizeSvg(content)
    return
  }

  // 如果是 SVG URL，则 fetch
  if (!isSvgUrl(content)) {
    return
  }

  try {
    isLoadingSvg.value = true
    const response = await fetch(content)
    if (!response.ok) throw new Error('Failed to fetch SVG')

    const svgText = await response.text()
    remoteSvgContent.value = sanitizeSvg(svgText)
  } catch (error) {
    console.error('[ModelAvatar] SVG URL fetch 失败:', error)
    remoteSvgContent.value = ''
  } finally {
    isLoadingSvg.value = false
  }
}

// 检查是否应该渲染 SVG（源代码或 URL）
const shouldRenderSvg = (content: string): boolean => {
  return isSvgCode(content) || isSvgUrl(content)
}

// 监听 modelAvatar 的变化，如果是 SVG 则获取/处理内容
watchEffect(() => {
  const avatarUrl = props.modelAvatar

  if (avatarUrl && shouldRenderSvg(avatarUrl)) {
    fetchSvgContent(avatarUrl)
  } else {
    remoteSvgContent.value = ''
  }
})

// 判断当前是否应该使用 SVG 渲染
const shouldUseSvgRender = computed(() => {
  const avatarUrl = props.modelAvatar
  return avatarUrl && shouldRenderSvg(avatarUrl) && remoteSvgContent.value
})

