}

const robotAvatarIcon = computed(() => {
  if (!props.model) return null

  const modelLower = props.model.toLowerCase()

  // 遍历映射查找匹配的图标
  for (const [key, iconName] of Object.entries(modelIconMap)) {
    if (modelLower.includes(key)) {
      return iconName
    }
  }

  return null
})

// 获取SVG内容
const currentSvgContent = computed(() => {
  if (!robotAvatarIcon.value) return ''

  const svgContent = svgContents[robotAvatarIcon.value]

  return svgContent || ''
})

interface Props {
  model?: string
  modelAvatar?: string
  modelName?: string
  size?: 'sm' | 'md' | 'lg'
}

// 根据 size 计算尺寸class
const sizeClasses = computed(() => {
  const sizeMap = {
    sm: 'h-6 w-6',
    md: 'h-8 w-8',
    lg: 'h-10 w-10',
  }
  return sizeMap[props.size || 'md']
})

const iconSizeClasses = computed(() => {
  const iconSizeMap = {
    sm: 'w-4 h-4',
    md: 'w-5 h-5',
    lg: 'w-6 h-6',
  }
  return iconSizeMap[props.size || 'md']
})
</script>

<template>
  <!-- 优先级 1: 如果有 modelAvatar（包括远程 SVG），优先显示 -->
  <div
    v-if="shouldUseSvgRender"
    :class="[
      'inline-flex items-center justify-center rounded-full border border-gray-100 dark:border-gray-700 border-solid shadow-sm bg-white dark:bg-gray-750',
      sizeClasses,
    ]"
  >
    <div v-if="!isLoadingSvg" :class="iconSizeClasses" v-html="remoteSvgContent" />
    <!-- 加载中状态 -->
    <div
      v-else
      :class="[iconSizeClasses, 'animate-pulse bg-gray-300 dark:bg-gray-600 rounded-full']"
    ></div>
  </div>
  <!-- 优先级 2: 普通图片 URL（非 SVG） -->
  <img
    v-else-if="isString(modelAvatar) && modelAvatar.length > 0 && !isSvgUrl(modelAvatar)"
    :class="[
      'inline-flex items-center justify-center rounded-full border border-gray-100 dark:border-gray-750 border-solid shadow-sm object-cover',
      sizeClasses,
    ]"
    :src="modelAvatar"
    :alt="modelName || 'Model Avatar'"
  />
  <!-- 优先级 3: 内置 SVG 图标（仅当没有 modelAvatar 时） -->
  <div
    v-else-if="!modelAvatar && robotAvatarIcon && currentSvgContent"
    :class="[
      'inline-flex items-center justify-center rounded-full border border-gray-100 dark:border-gray-700 border-solid shadow-sm bg-white dark:bg-gray-750',
      sizeClasses,
    ]"
  >
    <div :class="iconSizeClasses" v-html="currentSvgContent" />
  </div>
  <!-- 优先级 4: 文字头像作为最终 fallback -->
  <span
    v-else
    :class="[
      'select-none inline-flex items-center justify-center rounded-full border border-gray-200 dark:border-gray-700 border-solid dark:bg-gray-500 text-gray-600 dark:text-white font-semibold',
      sizeClasses,
      size === 'sm' ? 'text-xs' : size === 'lg' ? 'text-lg' : 'text-base',
    ]"
  >
    <span class="flex items-center justify-center w-full h-full">
      {{ modelName ? modelName.charAt(0).toUpperCase() : 'AI' }}
    </span>
  </span>
</template>
